import json

with open('/tmp/task_f8c13730_input.json') as f:
    test_input = json.load(f)

n, m = len(test_input), len(test_input[0])

# Key insight: input rows 14,15 have 2s but their vertical mirrors (9,8) are CLEAN
# So output[14], output[15] can be filled from input[9], input[8]

# But output[10], output[13] both have 2s - their vertical mirrors ALSO have 2s
# So we get 0s

# Solution: for mutual-2s positions, use values from the pairs in row 9,8 (LOD0) or
# the pairs in row 8,7 if those have 2s, etc.

# Let me find which rows have 2s:
for r in range(n):
    if any(test_input[r][c] == 2 for c in range(m)):
        print(f"Row {r} has 2s")

# So rows 10-15 have 2s, rows 8,9 do not

# The strategy: for any 2 at (r,c), find a non-2 value at position (r',c)
# where r' is any row that's a "clean" vertical mirror or close to it

def solve_with_neighbor_fallback(grid):
    result = [[0]*m for _ in range(n)]

    # Step 1: Fill using horizontal mirrors first
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 2:
                result[r][c] = grid[r][m-1-c]
            else:
                result[r][c] = grid[r][c]

    # Step 2: For remaining 2s, use vertical mirrors from clean rows
    for r in range(n):
        for c in range(m):
            if result[r][c] == 2:
                # Try vertical mirror first
                vm = grid[n-1-r][c]
                if vm != 2:
                    result[r][c] = vm
                else:
                    # Try the row just above or below (closer to clean rows)
                    for dr in [-1, 1]:
                        nr = n - 1 - r + dr
                        if 0 <= nr < n:
                            if r == nr:
                                continue
                            vnc = grid[nr][c]
                            if vnc != 2:
                                result[r][c] = vnc
                                break
                    if result[r][c] == 2:
                        # Try diagonal of all mirror rows
                        for nc in range(m):
                            if grid[r][nc] != 2:
                                result[r][c] = grid[r][nc]
                                break
                        else:
                            result[r][c] = 0  # last resort

    return result

output = solve_with_neighbor_fallback(test_input)

# Verify
print("Horizontal symmetry:")
all_h = all(all(output[r][c] == output[r][m-1-c] for c in range(m)) for r in range(n))
