# Demo rule: output[r] mirrors input[n-1-r]
# For 2s: look at input[r][c] symmetric positions (horz/vert/diag)
# If all have 2, use ANY non-2 from the global input (picking from nearest row)

def solve_final_demo_rule(input_grid):
    result = [[0]*m for _ in range(n)]

    # Step 1: Initialize with vertical reflection
    for r in range(n):
        for c in range(m):
            result[r][c] = input_grid[n-1-r][c]

    # Step 2: Fill 2s by searching from all symmetric positions
    for r in range(n):
        for c in range(m):
            if result[r][c] == 2:
                # Try all symmetric positions in ORIGINAL grid
                targets = [
                    (n-1-r, c),        # vertical mirror
                    (r, m-1-c),        # horizontal mirror  
                    (n-1-r, m-1-c),    # diagonal
                ]
                filled = None
                for tr, tc in targets:
                    if input_grid[tr][tc] != 2:
                        filled = input_grid[tr][tc]
                        break

                if filled is None:
                    # All symmetric positions are 2
                    # Use first non-2 from any position in source row
                    non_2 = [input_grid[n-1-r][k] for k in range(m) if input_grid[n-1-r][k] != 2]
                    fill = non_2[0] if non_2 else 9
                    result[r][c] = fill
                else:
                    result[r][c] = filled

    # Step 3: Enforce horizontal symmetry within each row
    for r in range(n):
        for c in range(m // 2):
            if result[r][c] != result[r][m-1-c]:
                # Pick non-2 value from the mismatch
                if result[r][c] != 2:
                    result[r][m-1-c] = result[r][c]
                elif result[r][m-1-c] != 2:
                    result[r][c] = result[r][m-1-c]
                else:
                    # Both 2 - use original input at either position
                    result[r][c] = input_grid[r][c]
                    result[r][m-1-c] = input_grid[r][c]

    # Enforce vertical symmetry
    for r in range(n // 2):
        for c in range(m):
            if result[r][c] != result[n-1-r][c]:
                if result[r][c] != 2:
                    result[n-1-r][c] = result[r][c]
                elif result[n-1-r][c] != 2:
                    result[r][c] = result[n-1-r][c]
                else:
                    result[r][c] = input_grid[r][c]
                    result[n-1-r][c] = input_grid[r][c]

    return result

